        i = tst('{a}').interpolations[0]
        self.assertEqual(type(i).__name__, 'Interpolation')
        self.assertEqual(type(i).__qualname__, 'Interpolation')
        # BACKPORT: this shows a different module name than upstream (tstrings vs string.templatelib)
        self.assertEqual(type(i).__module__, 'tstrings')

