    def test_template_values(self):
        t = tst('Hello, world')
        self.assertEqual(t.values, ())
        name = 'Lys'
        t = tst('Hello, {name}')
        self.assertEqual(t.values, ('Lys',))
        country = 'GR'
        age = 0
        t = tst('Hello, {name}, {age} from {country}')
        self.assertEqual(t.values, ('Lys', 0, 'GR'))

